'use strict';

// MAIN //

/**
* Groups contiguous lines into single text blocks.
*
* @private
* @param {Array<Object>} lines - array of line objects
* @returns {Array<Object>} grouped lines
*
* @example
* var lines = [
*     { 'text': 'a', 'line': 1 },
*     { 'text': 'b', 'line': 2 }
* ];
* var out = groupContiguousLines( lines );
* // returns [ { 'text': 'a\\nb', 'line': 1 } ]
*/
function groupContiguousLines( lines ) {
	var curr;
	var out;
	var i;

	if ( lines.length === 0 ) {
		return [];
	}

	out = [];
	curr = {
		'text': lines[ 0 ].text,
		'line': lines[ 0 ].line
	};

	for ( i = 1; i < lines.length; i++ ) {
		if ( lines[ i ].line === lines[ i - 1 ].line + 1 ) {
			curr.text += '\n' + lines[ i ].text;
		} else {
			out.push( curr );
			curr = {
				'text': lines[ i ].text,
				'line': lines[ i ].line
			};
		}
	}
	out.push( curr );

	return out;
}


// EXPORTS //

module.exports = groupContiguousLines;
